"""Show only verified R04 materials/sprites, without claiming complete maps or roofs."""
from pathlib import Path
import json,html,importlib.util
ROOT=Path(__file__).resolve().parents[1];P=ROOT/'src/Art/hd2d_26x26_20261013/batches/R04-pass-v1'
def read(n):return json.loads((P/n).read_text(encoding='utf-8'))
def main():
    assert read('materials-validation.json')['passed'] and read('sprites-validation.json')['passed'];sprites=read('sprite-manifest.json')['assets'];tiles=[a for a in read('materials-manifest.json')['assets'] if a['role']=='flat_edge_matched_material_variant'];cards=[]
    spec=importlib.util.spec_from_file_location('r04_labels',ROOT/'tools/Package-Hd2dR04.py');labels_module=importlib.util.module_from_spec(spec);spec.loader.exec_module(labels_module);labels=[labels_module.LABELS[a['id'][4:]] for a in sprites]
    for a,n in zip(sprites,labels):cards.append(f'<article><div class="sprite"><img src="{a["path"]}" alt="{n}"></div><h2>{n}</h2><p>{a["size"][0]}×{a["size"][1]} · 原点({a["origin"][0]},{a["origin"][1]})</p><a href="{a["path"]}" download>PNG</a></article>')
    blocks=[]
    for k,n in [('cobble','赭灰铺石'),('brick','冷灰砖面'),('boards','旧木板'),('earth','泥土与草屑')]:
        items=[a for a in tiles if a['material']==k];blocks.append(f'<article class="material"><h2>{n} · 9种26×26瓦片</h2><div class="tiles">'+''.join(f'<img src="{a["path"]}" alt="{n}变体{a["variant"]}">' for a in items)+f'</div><img class="macro" src="assets/backgrounds/r04_{k}__material.png" alt="{n}大纹理"></article>')
    out='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>柏石关 · 场景制作中</title><style>*{box-sizing:border-box}body{margin:0;background:#151a1c;color:#e4ded1;font:15px "Microsoft YaHei",sans-serif}main{max-width:1260px;margin:auto;padding:28px}h1{font-size:28px;margin:0 0 12px}h2{font-size:17px;margin:10px 0}p{color:#bcb7aa;line-height:1.6;margin:7px 0}a{color:#d6b879}header{padding-bottom:20px;border-bottom:1px solid #48504d}.gallery{display:grid;grid-template-columns:repeat(auto-fit,minmax(270px,1fr));gap:18px;margin:24px 0}article{background:#202728;border:1px solid #48504d;padding:16px;border-radius:5px}.sprite{height:270px;display:flex;align-items:center;justify-content:center;background:repeating-conic-gradient(#343a38 0% 25%,#272e2c 0% 50%) 50%/20px 20px}.sprite img{image-rendering:pixelated;max-width:100%;max-height:260px;object-fit:contain}.tiles{display:grid;grid-template-columns:repeat(3,52px);gap:0;margin:18px auto;width:156px}.tiles img{width:52px;height:52px;image-rendering:pixelated}.macro{display:block;width:100%;max-width:312px;margin:auto;image-rendering:pixelated}footer{border-top:1px solid #48504d;padding:20px 0;color:#bcb7aa}</style><main><header><h1>柏石关 · R04场景制作中</h1><p>建筑、环境物件与地面材料已拆分。完整地图、室内空间和屋顶分层正在制作。</p><p>六座建筑＋八件环境物件；四类地面各九个瓦片，另有四张大纹理。</p><a href="../../index.html">返回场景素材库</a></header><div id="sprites" class="gallery">__SPRITES__</div><h1>地面材料</h1><p>瓦片以200%显示；旁边保留312×312大纹理，供大面积铺面使用。</p><div id="materials" class="gallery">__MATERIALS__</div><footer>本页为制作进度预览。R04的22项地图/场地视图尚未完成，未计入已交付视图；原生游戏装配和运行仍待验证。</footer></main></html>'''
    out=out.replace('柏石关 · 场景制作中','柏石关 · 独立场景素材').replace('柏石关 · R04场景制作中','柏石关 · R04独立场景素材').replace('建筑、环境物件与地面材料已拆分。完整地图、室内空间和屋顶分层正在制作。','建筑、环境物件与地面材料已拆分。完整地图、室内空间和屋顶分层见场景预览。').replace('六座建筑＋八件环境物件','六座建筑＋23件环境物件').replace('本页为制作进度预览。R04的22项地图/场地视图尚未完成，未计入已交付视图；原生游戏装配和运行仍待验证。','本页展示独立生产素材；完整22项视图见场景预览，原生游戏装配和运行仍待验证。').replace('返回场景素材库</a>','返回场景素材库</a> · <a href="preview.html">打开完整场景预览</a>')
    (P/'assets-preview.html').write_text(out.replace('__SPRITES__',''.join(cards)).replace('__MATERIALS__',''.join(blocks)),encoding='utf-8');print(json.dumps(dict(path=str(P/'assets-preview.html'),sprites=len(sprites),tiles=len(tiles)),ensure_ascii=False))
if __name__=='__main__':main()
